//! Whether a worker should sit out a cycle: a logistic model fitted offline.
//!
//! Generated by `pareto_weight_calibration.logistic_runtime`, candidate `logistic-05-sqrt`.
//! Training artifact SHA-256 `f382e9d306d0a0cbb70213383459d002ef856e6f3902c7b7537291f6916c15dc`,
//! dataset SHA-256 `bee6cdcb324fb1c2c68788bf6cbb2783723fde617521dc09621af7ea9447e4a3`. Regenerate it
//! rather than editing the weights.

/// The logit of the 0.45 probability the model idles at.
const LOGIT_THRESHOLD: f64 = -0.20067069546215124;
const INTERCEPT: f64 = -2.643817471080609;

/// Whether the worker of `rank` among `registered_workers` should idle, given its productive
/// upstream handles, the smoothed body cost in nanoseconds and the contention in `[0, 1]`.
pub(super) fn should_idle(
    rank: usize,
    productive_handles: u64,
    registered_workers: usize,
    body_cost_ns: f64,
    contention: f64,
) -> bool {
    score(
        rank,
        productive_handles,
        registered_workers,
        body_cost_ns,
        contention,
    ) >= LOGIT_THRESHOLD
}

/// The model's logit.
pub(super) fn score(
    rank: usize,
    productive_handles: u64,
    registered_workers: usize,
    body_cost_ns: f64,
    contention: f64,
) -> f64 {
    let productive_ratio = productive_handles as f64 / registered_workers as f64;
    let log_workers = (registered_workers as f64).ln();
    let body = body_cost_ns.ln_1p();
    let z_rank = (rank as f64 - 4.319044216248458) / 4.1181433661913065;
    let z_ratio = (productive_ratio - 0.4622763757547462) / 0.33724380301220946;
    let z_workers = (log_workers - 2.667804090854188) / 0.4901351282564824;
    let z_body = (body - 4.65009657333485) / 0.9912481295736798;
    let z_contention = (contention - 0.4474590877565059) / 0.38529526416306775;

    let mut result = INTERCEPT;
    result += 0.4241650904189753 * z_rank;
    result += -0.2031033180323249 * z_ratio;
    result += 0.0 * z_workers;
    result += -0.6314678834474282 * z_body;
    result += 0.7694883160744411 * z_contention;
    result += 0.0 * z_rank * z_ratio;
    result += -0.03395423986927718 * z_rank * z_body;
    result += 0.44259833262386755 * z_rank * z_contention;
    result += 0.08703074460828884 * z_body * z_ratio;
    result += -0.1853465591892819 * z_contention * z_ratio;
    result += -1.581531213003884 * z_body * z_contention;
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn matches_the_fitted_model_on_reference_points() {
        // Logits of the upstream model.
        for (rank, productive, workers, body, contention, logit) in [
            (2, 1, 8, 100.0, 0.9, -1.7605688814085094),
            (8, 2, 16, 50.0, 0.95, 1.737208711759987),
            (3, 0, 4, 10_000.0, 0.1, -0.13891365758698182),
            (12, 4, 16, 200.0, 0.5, -2.1275043587734475),
            (8, 2, 16, 50.0, 0.05, -4.09420382484942),
        ] {
            let actual = score(rank, productive, workers, body, contention);
            assert!(
                (actual - logit).abs() < 1e-12,
                "{rank} {productive} {workers} {body} {contention}: {actual} vs {logit}"
            );
        }
    }

    #[test]
    fn idles_at_or_above_the_threshold_logit() {
        assert!(should_idle(8, 2, 16, 50.0, 0.95));
        assert!(should_idle(3, 0, 4, 10_000.0, 0.1));
        assert!(!should_idle(2, 1, 8, 100.0, 0.9));
        assert!(!should_idle(8, 2, 16, 50.0, 0.05));
    }
}
